const API_KEY = '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';

interface CodeReviewResponse {
  review: string;
  score: number;
  suggestions: string[];
}

export const reviewCode = async (code: string, taskDescription: string): Promise<CodeReviewResponse> => {
  try {
    const response = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${API_KEY}`
      },
      body: JSON.stringify({
        model: "gpt-4",
        messages: [
          {
            role: "system",
            content: "Вы - эксперт по программированию. Проанализируйте код и дайте подробный отзыв."
          },
          {
            role: "user",
            content: `Задача: ${taskDescription}\n\nКод решения:\n${code}\n\nПожалуйста, проанализируйте код и дайте:\n1. Общую оценку от 0 до 10\n2. Подробный отзыв\n3. Список рекомендаций по улучшению`
          }
        ],
        temperature: 0.7
      })
    });

    if (!response.ok) {
      throw new Error('Ошибка при проверке кода');
    }

    const data = await response.json();
    const reviewText = data.choices[0].message.content;

    // Парсим ответ от GPT
    const scoreMatch = reviewText.match(/оценка[:\s]+(\d+)/i);
    const score = scoreMatch ? parseInt(scoreMatch[1]) : 5;

    // Разделяем отзыв и рекомендации
    const parts = reviewText.split(/рекомендации|улучшения/i);
    const review = parts[0].trim();
    const suggestions = parts[1]
      ? parts[1].split('\n')
          .map((s: string) => s.trim())
          .filter((s: string) => s && !s.match(/рекомендации|улучшения/i))
      : [];

    return {
      review,
      score,
      suggestions
    };
  } catch (error) {
    console.error('Ошибка при отправке кода на проверку:', error);
    throw error;
  }
};
